tests_py:
def test_no_merges():
    assert solution.bpe_encode("cat", []) == ["c", "a", "t"]

def test_single_merge():
    assert solution.bpe_encode("the", [("t", "h"), ("th", "e")]) == ["the"]

def test_merge_order_matters():
    assert solution.bpe_encode("abc", [("a", "b"), ("b", "c")]) == ["ab", "c"]
    assert solution.bpe_encode("abc", [("b", "c"), ("a", "bc")]) == ["abc"]

def test_no_overlap():
    assert solution.bpe_encode("aaa", [("a", "a")]) == ["aa", "a"]

def test_empty_word():
    assert solution.bpe_encode("", [("a", "b")]) == []

def test_does_not_mutate_merges():
    merges = [("t", "h"), ("th", "e")]
    before = list(merges)
    solution.bpe_encode("the", merges)
    assert merges == before
